/* code -> icon */
const uint16_t *weather_icon_find(int code)
{
    switch (code) {
    case 0: return icon_sun;
    case 1: return icon_sun_cloud;
    case 2: return icon_cloud;
    case 3: return icon_rain1;
    case 4: return icon_rain2;
    case 5: return icon_rain3;
    case 6: return icon_rainstorm;
    case 7: return icon_thunder;
    case 8: return icon_snow;
    case 9: return icon_snow;
    case 10: return icon_snow_heavy;
    case 11: return icon_sleet;
    case 12: return icon_fog;
    case 13: return icon_haze;
    case 14: return icon_dust;
    case 15: return icon_wind;
    default: return icon_unknown;
    }
}
